/** Resolves a model's option ids into a full selection. */
export function selectionFor(model: NationalModel): ContextSelection {
  const sel = defaultContext();
  for (const f of FACTORS) {
    const optionId = model.options[f.id];
    const index = f.options.findIndex((o) => o.id === optionId);
    if (index >= 0) sel[f.id] = index;
  }
  return sel;
}
